import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Ownership","description":"","frontmatter":{},"headers":[],"relativePath":"repair-station-business/ownership.md","filePath":"repair-station-business/ownership.md"}'),i={name:"repair-station-business/ownership.md"};function o(r,e,l,h,p,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h1><h2 id="putting-a-station-on-sale" tabindex="-1">Putting a station on sale <a class="header-anchor" href="#putting-a-station-on-sale" aria-label="Permalink to &quot;Putting a station on sale&quot;">​</a></h2><p>Only stations that are on sale can be bought. As an admin with <code>nay_repair_business.config</code>:</p><ol><li>Create your stations with the <a href="/repair-station/stations">Repair Station editor</a>.</li><li>Open the admin panel with <code>/nay:repairbusiness</code>, or from the <strong>Manage stations for sale</strong> action in <code>/nay</code>.</li><li>Pick a station, type a sale price and press <strong>Set for sale</strong>.</li></ol><p>The same list is available in <code>/nay</code> as <strong>Stations for sale</strong>. A station for sale shows a map blip and a prompt with its price. While nobody owns it, <strong>Stations for sale without owner</strong> decides whether it stays open (players repair there as usual) or closes until someone buys it.</p><h2 id="buying" tabindex="-1">Buying <a class="header-anchor" href="#buying" aria-label="Permalink to &quot;Buying&quot;">​</a></h2><p>A player walks to the station and presses <strong>E</strong>. A confirmation shows the price and the account it is paid from (<strong>Purchase account</strong>). The player can own up to <strong>Stations per player</strong> stations. The purchase is checked on the server, within 8 meters of the station, and refunded if anything fails.</p><h2 id="the-tablet" tabindex="-1">The tablet <a class="header-anchor" href="#the-tablet" aria-label="Permalink to &quot;The tablet&quot;">​</a></h2><p>The owner presses <strong>E</strong> at the station to open the tablet, from 8 meters or less:</p><ul><li><strong>Overview</strong>: stock, till, repairs of the day and of the last 7 days, last operations.</li><li><strong>Stock</strong>: buy parts or hand in items, see <a href="/repair-station-business/stock">Stock</a>.</li><li><strong>Till</strong>: take money to cash or bank, or put money from the bank in the till.</li><li><strong>Settings</strong>: price percentage, station name, sale of the station.</li></ul><p>The station name chosen by the owner replaces the station name in the repair menu. The percentage scales the price of every service: players see the final price before paying, and the tax (<strong>Tax</strong>) is kept on each payment, so the till receives the rest.</p><h2 id="selling-and-losing-a-station" tabindex="-1">Selling and losing a station <a class="header-anchor" href="#selling-and-losing-a-station" aria-label="Permalink to &quot;Selling and losing a station&quot;">​</a></h2><ul><li><strong>Selling</strong>: the owner is paid <strong>Sell back</strong> percent of the purchase price, plus the till, in the bank. The station is back on sale at its price.</li><li><strong>Eviction</strong>: staff can evict an owner from the admin panel. The owner is paid like for a sale.</li><li><strong>Inactivity</strong>: an owner who does not open the tablet for <strong>Inactivity limit</strong> days loses the station and is paid like for a sale. 0 turns it off.</li><li><strong>Station removed</strong>: when a station is deleted in the Repair Station editor, its owner is paid like for a sale and the business forgets it.</li></ul><p>An owner who is offline when this happens receives the money, once, the next time the character is loaded, with a notification. Every operation is recorded in the ledger, readable with the <a href="/repair-station-business/api">API</a>.</p>',14)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
